/// <summary>
/// Class to extend for indbound integrations
/// </summary>
public abstract class IntegrationInbound_INT  extends Integration_INT
{
}

Method.Source:
/// <summary>
/// Direction for an inbound Integration
/// </summary>
/// <returns>The direction</returns>
public IntegrationDirection_INT Direction()
{
    return IntegrationDirection_INT::In;
}

/// <summary>
/// Does integration supports transfer from RAW to Proceseed 
/// </summary>
/// <returns></returns>
public IntegrationSupportsParsed_INT supportsParsed()
{
    return false;
}
